import{_ as o,C as a,c as l,o as i,aa as c,G as t}from"./chunks/framework.ByRpVre_.js";const n="/assets/control-panel-system.8_bTe5ns.png",s="/assets/system-properties-interface.B5MsGSCV.png",p="/assets/system-variable.ClABU0vQ.png",g="/assets/gradle-maven-version-info.B_6ljqmB.png",h="/assets/craft-engine-code.BmSvKEA6.png",b="/assets/extrastorage-code.D5V7oTpr.png",M=JSON.parse('{"title":"用 Gradle 或 Maven 构建 Jar","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/guide"},{"title":"self-help","link":""},{"title":"用 Gradle 或 Maven 构建 Jar","link":"/guide/self-help/build-jars-with-gradle-or-maven"}]},"headers":[],"relativePath":"guide/self-help/build-jars-with-gradle-or-maven.md","filePath":"guide/self-help/build-jars-with-gradle-or-maven.md"}'),m={name:"guide/self-help/build-jars-with-gradle-or-maven.md"};function u(f,e,v,_,G,x){const d=a("NolebaseGitContributors"),r=a("NolebaseGitChangelog");return i(),l("div",null,[e[0]||(e[0]=c('<h1 id="用-gradle-或-maven-构建-jar" tabindex="-1">用 Gradle 或 Maven 构建 Jar <a class="header-anchor" href="#用-gradle-或-maven-构建-jar" aria-label="Permalink to &quot;用 Gradle 或 Maven 构建 Jar&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">阅前注意</p><p>本章节使用到的工具可以从这里下载：<br> Gradle（推荐安装 8.14.3）：<a href="https://gradle.org/releases/" target="_blank" rel="noreferrer">https://gradle.org/releases/</a><br> Maven：<a href="https://maven.apache.org/download.cgi?." target="_blank" rel="noreferrer">https://maven.apache.org/download.cgi?.</a></p></div><h2 id="_01-下载安装-gradle-maven" tabindex="-1">01. 下载安装 Gradle/Maven <a class="header-anchor" href="#_01-下载安装-gradle-maven" aria-label="Permalink to &quot;01. 下载安装 Gradle/Maven&quot;">​</a></h2><p>不同于一般的软件，Gradle/Maven 需要手动下载二进制文件，并通过系统环境对文件进行关联。</p><h3 id="gradle" tabindex="-1">Gradle <a class="header-anchor" href="#gradle" aria-label="Permalink to &quot;Gradle&quot;">​</a></h3><p>从上述的官网下载到 Gradle 后，将文件解压到合适的位置，例如 <code>D:/gradle</code>。</p><p>另外，还需要准备一个存储依赖库的文件夹，例如 <code>D:/gradleUserHome</code>。</p><p>之后，打开设置面板，搜索“环境变量”，在“系统”下找到带着盾牌符号的“编辑系统环境变量”。</p><figure><img src="'+n+'" alt="" tabindex="0"><figcaption>点进去，就对了。</figcaption></figure><p>在弹出的窗口中点击“环境变量”，再找到下侧的“系统变量（S）”，新增/追加如下内容：</p><figure><img src="'+s+'" alt="" tabindex="0"><figcaption></figcaption></figure><table tabindex="0"><thead><tr><th>变量名称</th><th>变量值</th><th>示例</th><th>解释</th></tr></thead><tbody><tr><td><code>GRADLE_HOME</code></td><td><code>&lt;上述的解压路径&gt;</code></td><td><code>D:/gradle</code></td><td>Gradle 的主目录</td></tr><tr><td><code>GRADLE_USER_HOME</code></td><td><code>&lt;上述的存储依赖库路径&gt;</code></td><td><code>D:/gradleUserHome</code></td><td>用于存放 Gradle 下载的依赖库。<br>尽可能放在空间充足的地方。</td></tr><tr><td><code>Path</code></td><td><code>&lt;上述的解压路径&gt;/bin</code></td><td><code>D:/gradle/bin</code></td><td>用于通过命令行启动 Gradle。<br>需要注意的是，Path 变量会由多个程序用到，因此需要在弹出的编辑框中点击“新增”，再把路径填入。</td></tr></tbody></table><figure><img src="'+p+'" alt="" tabindex="0"><figcaption>修改后的系统环境变量窗口</figcaption></figure><p>此时，点击下方的“确定”即可保存系统变量。</p><h3 id="maven" tabindex="-1">Maven <a class="header-anchor" href="#maven" aria-label="Permalink to &quot;Maven&quot;">​</a></h3><p>从上述的官网下载到 Maven 后，将文件解压到合适的位置，例如 <code>D:/maven</code>。</p><p>与 Gradle 相同，Maven 也需要准备一个存储依赖库的文件夹，不过我们稍后会讲到如何设置。</p><p>按上述 Gradle 的操作方式添加如下系统变量：</p><table tabindex="0"><thead><tr><th>变量名称</th><th>变量值</th><th>示例</th><th>解释</th></tr></thead><tbody><tr><td><code>MAVEN_HOME</code></td><td><code>&lt;上述的解压路径&gt;</code></td><td><code>D:/maven</code></td><td>Maven 的主目录</td></tr><tr><td><code>Path</code></td><td><code>&lt;上述的解压路径/bin&gt;</code></td><td><code>D:/maven/bin</code></td><td>用于通过命令行启动 Maven。<br>注意点与 Gradle 部分相同。</td></tr></tbody></table><p>准备完毕后，打开 <code>&lt;安装目录&gt;/maven/conf/settings.xml</code> 文件，按<a href="https://zhuanlan.zhihu.com/p/625000667" target="_blank" rel="noreferrer">这篇教程</a>第四步和第五步所说，对镜像库和存储目录进行配置。</p><h2 id="_02-验证-gradle-maven-是否正确安装" tabindex="-1">02. 验证 Gradle/Maven 是否正确安装 <a class="header-anchor" href="#_02-验证-gradle-maven-是否正确安装" aria-label="Permalink to &quot;02. 验证 Gradle/Maven 是否正确安装&quot;">​</a></h2><p>按 Win+R 键，输入 <code>cmd</code> 后回车，或手动呼出命令行界面，输入 <code>gradle -version</code> 或 <code>mvn version</code>。</p><p>如果出现下图的提示，说明你已经安装成功了。</p><figure><img src="'+g+'" alt="" tabindex="0"><figcaption>上方为 Maven，下方则为 Gradle</figcaption></figure><h2 id="_03-执行构建命令" tabindex="-1">03. 执行构建命令 <a class="header-anchor" href="#_03-执行构建命令" aria-label="Permalink to &quot;03. 执行构建命令&quot;">​</a></h2><p>打开插件目录，在文件浏览器的地址一栏输入 <code>cmd</code>，按回车。</p><p>在弹出的界面中输入 <code>gradle build</code>（Gradle 构建器）或 <code>mvn package</code>（Maven 构建器），静待下载依赖完成并开始构建即可。</p><p>输出的插件可以在 <code>&lt;插件目录&gt;/build/libs</code> 中找到。</p><h2 id="ex-后记" tabindex="-1">ex. 后记 <a class="header-anchor" href="#ex-后记" aria-label="Permalink to &quot;ex. 后记&quot;">​</a></h2><h3 id="_01-关于从源代码构建" tabindex="-1">01. 关于从源代码构建 <a class="header-anchor" href="#_01-关于从源代码构建" aria-label="Permalink to &quot;01. 关于从源代码构建&quot;">​</a></h3><p>有些时候，仓库里可能会有一个 <code>gradlew.bat</code> 文件。这是便携式的 Gradle 构建脚本，你可以用 <code>gradlew.bat clean build</code> 或 <code>gradlew.bat build</code> 进行构建，这样做的好处是不需要下载和配置 Gradle 和系统环境变量。缺点是，每次使用不同的构建时都会往存储目录里安装不同版本的 Gradle，浪费大量空间。</p><p>另外，有些源代码构建时需要修改构建脚本。例如，PlotSquared v7 会提醒你 fork 再修改代码，还会自动提交 commit，而本地构建是不需要这些功能的。此时需要进入构建脚本 <code>build.gradle.kts</code> 文件中去除相关代码，才可以顺利构建插件。</p><div class="warning custom-block"><p class="custom-block-title">警告</p><p>不要在没有安装 Gradle 的情况下试图构建插件/模组等需要 Gradle 参与构建的源码，这会导致其缓存文件生成在 C 盘挤占空间。</p><p>如果你不小心这么做了，请使用诸如 WizTree 等的软件将 C 盘的 <code>.gradle</code> 文件夹删除。</p></div><h3 id="_02-关于构建类型的判别" tabindex="-1">02. 关于构建类型的判别 <a class="header-anchor" href="#_02-关于构建类型的判别" aria-label="Permalink to &quot;02. 关于构建类型的判别&quot;">​</a></h3><p>这个还是很好分辨的。使用 Gradle 构建的项目，一般会存在上述的 <code>gradlew.bat</code> 文件，除此之外，还会有 <code>build.gradle.kts</code>（构建脚本）、<code>gradle.properties</code>（Gradle 设置）这样的文件。</p><figure><img src="'+h+'" alt="" tabindex="0"><figcaption></figcaption></figure><p>以 craftengine 的源代码为例，这就是一个典型的利用了 Gradle 进行构建的插件。若需要构建这个插件，你可以使用命令 <code>gradle build</code>，或上述的 <code>gradlew.bat build</code> 构建插件。</p><p>而使用了 Maven 构建的项目，一般会有一个 <code>pom.xml</code> 文件，并且除了源代码外不会有其他文件的多余，这也是它备受推崇的原因之一。</p><figure><img src="'+b+'" alt="" tabindex="0"><figcaption></figcaption></figure><p>以 ExtraStorage 的源代码为例，这则是一个典型的利用了 Maven 进行构建的插件。若需要构建这个插件，你可以使用命令 <code>mvn package</code>。</p><h3 id="_03-下载依赖速度太慢" tabindex="-1">03. 下载依赖速度太慢 <a class="header-anchor" href="#_03-下载依赖速度太慢" aria-label="Permalink to &quot;03. 下载依赖速度太慢&quot;">​</a></h3><p>如果你在使用的是 Maven，则可以通过添加镜像源的方式解决。而如果你使用的是 Gradle，恐怕就没那么幸运了。</p><p>不过幸好我们有一个相对完善的解决方法——<a href="https://github.com/docmirror/dev-sidecar" target="_blank" rel="noreferrer">dev-sidecar</a>。</p><p>默认开启代理服务和系统代理，成功连接后就可以提升下载速度。</p>',44)),t(d),t(r)])}const q=o(m,[["render",u]]);export{M as __pageData,q as default};
